import sys
input = sys.stdin.read

def can_form_array(n, k, a):
    max_steps = 0
    for num in a:
        if num > 0:
            steps = 0
            while k**steps <= num:
                steps += 1
            max_steps = max(max_steps, steps)

    power_count = [0] * (max_steps + 1)

    for num in a:
        step = 0
        while num > 0:
            if num % k > 1:
                return False
            if num % k == 1:
                if power_count[step] > 0:
                    return False
                power_count[step] += 1
            num //= k
            step += 1

    return True

def main():
    data = input().split()
    index = 0
    T = int(data[index])
    index += 1
    results = []
    for _ in range(T):
        n, k = int(data[index]), int(data[index + 1])
        index += 2
        a = list(map(int, data[index:index + n]))
        index += n
        if can_form_array(n, k, a):
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

